const GAP = {
  dallasSplit: { status:"unquantified", title:"Dallas pre-season was split into several tournaments per day", text:"The official schedule says the March 8 and March 9 pre-season Regionals were each split into multiple tournaments. We count one top cut per day. If each sub-tournament had its own top cut, the true Dallas number is higher. [off2526s1]" },
  langs: { status:"unquantified", title:"Other language regions", text:"This page covers the English version (en.onepiece-cardgame.com). Asia-English, Japanese and Chinese championships use their own prize cards and are not included." },
  packUnit: { status:"unquantified", title:"Random pull — population is an expected value", text:"This card comes in a sealed prize pack with a random pull. We count the packs handed out at each placement, multiply by cards per pack, and divide by the number of card types in the pack. That is the expected number of copies, assuming Bandai printed every card in the pack in equal quantity; the exact number was never published." },
  cumulative: { status:"unquantified", title:"Placement tiers are counted as cumulative", text:"Bandai lists prizes per placement tier. We count every player who reached a tier as receiving that tier's prize, and players who placed higher as receiving every lower tier's prize as well (a champion also collects the Top 8 and Top 16 prizes). If a tier was exclusive instead, the number is lower." },
  setContents: { status:"unquantified", title:"Set contents are shown only as images", text:"Bandai's page shows the cards in this set as images with no card list in the text. The set is awarded as one unit, so every card in it has the same population as the set." },
  raid: { status:"unquantified", title:"Raid'n'Trade listed with three dates", text:"The Online Wave 2 page lists Raid'n'Trade (Europe) once with three dates (July 15, 22, 29). We count three tournaments. If it was one tournament spread over three days, subtract two events' worth. [on23w2]" },
};

